import { Input } from "@/components/ui/input";
import { useAuth } from "@/hooks/use-auth";

// ─── Types ────────────────────────────────────────────────────────────────────

type TaskStatus = "To Do" | "In Progress" | "In Review" | "Done";

interface Task {
  _id?: string;
  id?: string;
  title: string;
  scheduledDate: string;
  scheduledTime: string;
  platform: string;
  contentType: string;
  caption: string;
  hashtags: string;
  mediaUrl: string;
  reelVideoLink: string;
  campaign: string;
  company: string;
  assignedTo: string;
  notes: string;
  status: TaskStatus;
  approvalStatus: string;
}

const STATUSES: TaskStatus[] = ["To Do", "In Progress", "In Review", "Done"];
const PLATFORMS = [
  "Instagram",
  "Facebook",
  "X / Twitter",
  "LinkedIn",
  "YouTube Shorts",
  "WhatsApp Channel",
  "Google My Business",
];
const CONTENT_TYPES = [
  "Image Post",
  "Reel",
  "Video",
  "Carousel",
  "Story",
  "Blog Idea",
  "Text Post",
];

const STATUS_STYLE: Record<TaskStatus, string> = {
  "To Do": "bg-gray-100 text-gray-700 border-gray-300",
  "In Progress": "bg-blue-100 text-blue-700 border-blue-300",
  "In Review": "bg-amber-100 text-amber-700 border-amber-300",
  Done: "bg-green-100 text-green-700 border-green-300",
};

const APPROVAL_STYLE: Record<string, string> = {
  Pending: "bg-yellow-100 text-yellow-700",
  Approved: "bg-green-100 text-green-700",
  Rejected: "bg-red-100 text-red-700",
};

// ─── Day label helper ─────────────────────────────────────────────────────────
// Within a campaign group, assign D1, D2… based on sorted unique dates
function buildDayMap(tasks: Task[]): Map<string, string> {
  const uniqueDates = Array.from(
    new Set(tasks.map((t) => t.scheduledDate).filter(Boolean)),
  ).sort();
  const map = new Map<string, string>();
  uniqueDates.forEach((date, i) => map.set(date, `D${i + 1}`));
  return map;
}

